insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'b5a317be-6410-5767-a5bb-01002e617f6d', id, 'f0ae67ff-93d6-5f86-8de3-01c2c4c270da', 30, '10.a', 'Força e Equilíbrio: enrolar corretamente a fieira e lançá-lo de modo que gire pelo tempo mínimo de 20 segundos antes de perder o equilíbrio;', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '6416abb3-dda1-5578-8e42-f1b49289a0b3', id, 'f0ae67ff-93d6-5f86-8de3-01c2c4c270da', 31, '10.b', 'Técnica Apurada: lançar o pião, em seguida pegá-lo do chão para mão e, depois de alguns instantes, devolvê-lo ao chão ainda girando;', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'ad25fd33-56de-59e8-85d0-eea1167b1682', id, 'f0ae67ff-93d6-5f86-8de3-01c2c4c270da', 32, '10.c', 'Pôr pra Dormir. fazer com que o pião gire de modo que, por 10 segundos, ele permaneça no mesmo lugar e aparente estar parado;', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'cd288a8a-37e6-5a20-8b2a-61e4387fed7a', id, 'f0ae67ff-93d6-5f86-8de3-01c2c4c270da', 33, '10.d', 'Girada de Castelo: girar o pião invertido (de "cabeça para baixo") apoiado apenas no castelo;', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'f8e5189a-a7b6-591a-a29c-731a2720022f', id, 'f0ae67ff-93d6-5f86-8de3-01c2c4c270da', 34, '10.e', 'Deslizamento: enquanto o pião gira, com a ajuda da fieira, movimentar o pião de um lugar para outro sem derrubá-lo;', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'de85705a-c5a4-5294-9fce-da7964605882', id, 'f0ae67ff-93d6-5f86-8de3-01c2c4c270da', 35, '10.f', 'Precisão: lançar o pião de forma a acertar um alvo pré-determinado, como uma linha ou círculo no chão.', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '758117d0-d570-5185-a971-81aa750bf621', id, null, 36, '11', 'Completar ao menos uma das manobras:', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '667fa6c2-7ff4-5c5a-adfa-f2c6012f718f', id, '758117d0-d570-5185-a971-81aa750bf621', 37, '11.a', 'Fisgada no Ar: consiste em lançar o pião e antes que ele atinja o chão e a fieira se desenrole totalmente, fisgá-lo de volta, fazendo com que o pião gire na mão;', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '038634e8-fafd-50de-a491-a6c63640b52d', id, '758117d0-d570-5185-a971-81aa750bf621', 38, '11.b', 'Ponte ou Teleférico: com uma mão, segura os dois extremos da fieira e com a outra mão, a outra ponta que se forma. Estica-se então a fieira e na ponte que é formada recupera-se o pião ainda girando e, ao levantar uma das mãos, pode-se inclinar a fieira de tal maneira que o pião escorregue de um lado para o outro, enquanto permanece a girar.', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '1b4fb768-be55-5479-8218-c160f9b093b4', id, '758117d0-d570-5185-a971-81aa750bf621', 39, '11.c', 'Lançamento: enquanto o pião gira no chão, fazer um seio à sua ponteira e fazê-lo pular, puxando as pontas da fieira com agilidade e força, servindo de impulso. Realizar a manobra duas vezes, uma vez com o pião saltando e caindo no chão, e outra com ele saltando e caindo na mão.', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '74cb8757-ede6-5265-ab2a-27370c407e0e', id, null, 40, '12', 'Conhecer ou criar, ao menos, 4 jogos coletivos com piões Convidar seus companheiros de unidade para participar de cada um dos jogos. Ao final, conversar com o instrutor sobre como se sentiu durante a atividade e sobre as vantagens da prática de recreação ao ar livre.', '2026-09-29 06:07:04', null from especialidades where codigo = 'AR-106' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
