insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '639af5e9-a168-5ddb-9163-1ef5a4f57721', id, null, 7, '7', 'Demonstrar habilidade para utilizar ferramentas necessárias na construção de estruturas rústicas de grande porte, como facão, machado de mão, faca, serra de arco, amoladora, plaina elétrica e manual, formões, maços ou martelos grandes, chaves combinadas, chaves de tubo, furadeira elétrica com brocas para madeira de diferentes diâmetros.', '2026-09-29 18:23:45', null from especialidades where codigo = 'AR-116' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
